    {
        return time;
    }

    /**
     * Returns an instance of class Weather.
     */
    public Weather getWeather()
    {
        return weather;
    }

    public void advance(int step)
    {
        time.incrementTime();
        weather.checkWeatherChange(step);
    }

    public void reset()
    {
        time.reset();
        weather.reset();
    }

}

