226	            }
227	            if(!currentState.isViable()) {
228	                updateBestSimulationResult(completedSteps);
229	                playingSimulation = false;
230	            }
231	        }
232	
233	        remainingSteps = Math.max(0, numSteps - completedSteps);
234	    }
