237	     * Run the simulation from its current state for a single step.
238	     * Iterate over the whole field updating the state of each organism.
239	     */
240	    public void simulateOneStep()
241	    {
242	        if(!playingSimulation) {
243	            return;
244	        }
245	
246	        step++;
247	        environment.advanceTime();
248	        weatherService.advance();
249	
250	        List<Actor> newActors = new ArrayList<>();
251	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
252	            Actor actor = it.next();
253	            processActor(actor, newActors);
254	            maybeGrowPlant(actor);
255	
256	            if(!actor.isAlive()) {
257	                if(actor instanceof Organism organism) {
258	                    diseaseService.unregister(organism);
259	                }
260	                it.remove();
261	            }
262	        }
263	
264	        actors.addAll(newActors);
265	        actors.addAll(organismFactory.createGrassPatches(field, environment));
266	        publishState();
267	    }
